<script setup>
import {hasAdminPermission} from '~/utils/adminPermissions'
const {request}=useSupportClient(),{adminUser}=useAdminAccess(),scope=useCustomerScope(),data=ref(null),busy=ref(false),failed=ref(false),notice=ref(''),preview=ref(null),confirmation=ref('')
const contacts=ref(''),suppressPhone=ref(''),suppressReason=ref(''),settings=ref({}),selected=ref(null),{t}=useI18n()
const blank=()=>({title:'',template_id:'',locale:'all',tags_text:'',scheduled_at:new Date(Date.now()+3600000).toISOString(),budget_minor:0,recipient_limit:100}),draft=ref(blank())
let generation=0
const can=key=>hasAdminPermission(adminUser.value,'sms.marketing.'+key)
const load=async()=>{const g=generation;try{const r=await request('/api/admin-sms/marketing',{retry:0});scope.assertCurrent();if(g!==generation)return;data.value=r;settings.value={...r.settings.controls,enabled:r.settings.controls.is_enabled};selected.value=selected.value?r.settings.campaigns.find(x=>x.id===selected.value.id)||null:null}catch{if(g===generation)failed.value=true}}
const run=async body=>{if(busy.value)return;busy.value=true;failed.value=false;notice.value='';const g=generation;try{const r=await request('/api/admin-sms/marketing',{method:'POST',retry:0,body});scope.assertCurrent();if(g!==generation)return;if(body.action==='preview'||body.action==='prepare')preview.value=r.preview;else preview.value=null;if(body.action==='import'){contacts.value='';notice.value=t('smsMarketing.imported',{added:r.added,skipped:r.skipped})}if(body.action==='draft')selected.value=r;confirmation.value='';await load();return r}catch{if(g===generation)failed.value=true}finally{if(g===generation)busy.value=false}}
const importContacts=()=>{try{return run({action:'import',contacts:JSON.parse(contacts.value)})}catch{failed.value=true}}
const saveDraft=()=>run({action:'draft',id:selected.value?.state==='draft'?selected.value.id:null,revision:selected.value?.revision||0,draft:{...draft.value,tags:draft.value.tags_text.split(',').map(x=>x.trim()).filter(Boolean)}})
const choose=c=>{selected.value=c;draft.value={...c,tags_text:c.tags.join(',')};preview.value=null;confirmation.value=''}
const control=action=>run({action,id:selected.value.id,revision:selected.value.revision,confirmation:confirmation.value})
const exact=computed(()=>selected.value?`APPROVE ${selected.value.id} ${selected.value.revision} ${selected.value.planned_recipients} ${selected.value.planned_segments} ${selected.value.reserved_cost_minor} EGP`:'')
scope.onInvalidate(()=>{generation++;data.value=null;contacts.value='';selected.value=null;preview.value=null;settings.value={};suppressPhone.value='';suppressReason.value='';confirmation.value='';draft.value=blank();busy.value=false;failed.value=false;notice.value=''})
onMounted(load)
</script>
<template>
 <section class="sms-panel space-y-4"><h3 class="text-lg font-semibold">{{ t('smsMarketing.title') }}</h3><p class="text-sm">{{ t('smsMarketing.scope') }}</p><p v-if="failed" role="alert" class="text-sm text-red-700">{{ t('smsMarketing.failed') }}</p><p v-if="notice" role="status">{{ notice }}</p>
 <template v-if="data"><p class="text-sm">{{ t(data.runtimeEnabled?'smsMarketing.runtimeOn':'smsMarketing.runtimeOff') }} · {{ t(data.unsubscribeReady?'smsMarketing.unsubscribeReady':'smsMarketing.unsubscribeMissing') }}</p>
 <details v-if="can('configure')" class="rounded-lg border p-3"><summary>{{ t('smsMarketing.settings') }}</summary><form class="mt-3 grid gap-3 md:grid-cols-2" @submit.prevent="run({action:'settings',revision:data.settings.controls.revision,settings})">
 <label class="sms-check"><input v-model="settings.enabled" type="checkbox">{{ t('smsMarketing.enabled') }}</label><label class="sms-check"><input v-model="settings.unicode_accepted" type="checkbox">{{ t('smsMarketing.unicode') }}</label>
 <label class="sms-field">{{ t('smsMarketing.unitCost') }}<input v-model.number="settings.unit_cost_minor" type="number" min="1" max="100000"></label><label class="sms-field">{{ t('smsMarketing.commercialRef') }}<input v-model="settings.commercial_reference" minlength="8" maxlength="200" required></label>
 <label class="sms-field">{{ t('smsMarketing.recipientLimit') }}<input v-model.number="settings.max_recipients" type="number" min="1" max="500"></label><label class="sms-field">{{ t('smsMarketing.segmentLimit') }}<input v-model.number="settings.max_segments" type="number" min="1" max="10"></label><button class="sms-secondary" :disabled="busy">{{ t('sms.save') }}</button></form></details>
 <details v-if="can('consent')" class="rounded-lg border p-3"><summary>{{ t('smsMarketing.contacts') }}</summary><p class="my-3 text-sm">{{ t('smsMarketing.importHelp') }}</p><p class="text-xs" dir="ltr">phone, locale, tags[], opt_in, consented_at, consent_reference, source_reference</p><form class="space-y-3" @submit.prevent="importContacts"><label class="sms-field">{{ t('smsMarketing.consentJson') }}<textarea v-model="contacts" dir="ltr" rows="5" maxlength="250000" required></textarea></label><button class="sms-secondary" :disabled="busy">{{ t('smsMarketing.import') }}</button></form>
 <form class="mt-4 grid gap-3 md:grid-cols-3" @submit.prevent="run({action:'suppress',phone:suppressPhone,reason:suppressReason})"><label class="sms-field">{{ t('sms.recipient') }}<input v-model="suppressPhone" dir="ltr" maxlength="40" required></label><label class="sms-field">{{ t('smsMarketing.reason') }}<input v-model="suppressReason" maxlength="200" required></label><button class="sms-secondary" :disabled="busy">{{ t('smsMarketing.suppress') }}</button></form></details>
 <p class="text-sm">{{ t('smsMarketing.contactCounts',{contacts:data.settings.contacts,suppressed:data.settings.suppressed}) }}</p>
 <form v-if="can('manage')" class="grid gap-3 md:grid-cols-2" @submit.prevent="saveDraft"><label class="sms-field">{{ t('smsMarketing.campaignTitle') }}<input v-model="draft.title" maxlength="100" required></label><label class="sms-field">{{ t('sms.template') }}<select v-model="draft.template_id" required><option value="">—</option><option v-for="item in data.templates" :key="item.id" :value="item.id">{{ item.name }} ({{ item.revision }})</option></select></label>
 <label class="sms-field">{{ t('sms.language') }}<select v-model="draft.locale"><option value="all">{{ t('smsMarketing.both') }}</option><option value="en">English</option><option value="ar">العربية</option></select></label><label class="sms-field">{{ t('smsMarketing.tags') }}<input v-model="draft.tags_text" maxlength="400"></label>
 <label class="sms-field">{{ t('smsMarketing.schedule') }}<input v-model="draft.scheduled_at" dir="ltr" required></label><label class="sms-field">{{ t('smsMarketing.budget') }}<input v-model.number="draft.budget_minor" type="number" min="1" max="10000000" required></label><label class="sms-field">{{ t('smsMarketing.recipientLimit') }}<input v-model.number="draft.recipient_limit" type="number" min="1" max="500" required></label><div class="flex flex-wrap items-end gap-2"><button class="sms-secondary" :disabled="busy">{{ t('smsMarketing.saveDraft') }}</button><button class="sms-secondary" type="button" @click="selected=null;draft=blank();preview=null">{{ t('smsMarketing.newDraft') }}</button></div></form>
 <div class="overflow-x-auto"><table class="w-full text-start text-sm"><thead><tr><th>{{ t('smsMarketing.campaignTitle') }}</th><th>{{ t('sms.status') }}</th><th>{{ t('smsMarketing.reserved') }}</th><th>{{ t('smsMarketing.results') }}</th></tr></thead><tbody><tr v-for="item in data.settings.campaigns" :key="item.id" class="border-t"><td class="p-2"><button class="text-start underline" @click="choose(item)">{{ item.title }}</button></td><td class="p-2">{{ t('smsMarketing.states.'+item.state) }}</td><td class="p-2">{{ (item.reserved_cost_minor/100).toFixed(2) }} EGP</td><td class="p-2"><span v-for="(count,state) in item.outcomes" :key="state" class="me-3">{{ t('smsMarketing.outcomes.'+state) }}: {{ count }}</span></td></tr></tbody></table></div>
 <div v-if="selected" class="space-y-3 rounded-lg border p-3"><p class="break-all text-xs" dir="ltr">{{ selected.id }} · {{ selected.revision }}</p><p class="text-sm">{{ t('smsMarketing.plan',{recipients:selected.planned_recipients,segments:selected.planned_segments,cost:(selected.reserved_cost_minor/100).toFixed(2)}) }}</p>
 <div v-if="selected.state==='draft'&&can('manage')" class="flex gap-2"><button :disabled="busy" class="sms-secondary" @click="control('preview')">{{ t('smsMarketing.preview') }}</button><button :disabled="busy" class="sms-secondary" @click="control('prepare')">{{ t('smsMarketing.freeze') }}</button></div>
 <div v-if="preview" class="space-y-2 text-sm" aria-live="polite"><p>{{ t('smsMarketing.plan',{recipients:preview.recipients,segments:preview.segments,cost:(preview.cost_minor/100).toFixed(2)}) }}</p><p>{{ preview.encodings.join(', ') }}</p><p class="whitespace-pre-wrap" dir="ltr">{{ preview.preview_en }}</p><p class="whitespace-pre-wrap" dir="rtl">{{ preview.preview_ar }}</p></div>
 <form v-if="['review','paused'].includes(selected.state)&&can('approve')" class="space-y-3" @submit.prevent="control(selected.state==='paused'?'resume':'approve')"><p class="text-sm">{{ t('smsMarketing.approvalHelp') }}</p><p class="break-all text-xs" dir="ltr">{{ exact }}</p><label class="sms-field">{{ t('smsMarketing.confirmation') }}<input v-model="confirmation" dir="ltr" autocomplete="off" :maxlength="250" required></label><button :disabled="busy||confirmation!==exact" class="sms-secondary">{{ t('smsMarketing.approve') }}</button></form>
 <div v-if="can('manage')" class="flex gap-3"><button v-if="selected.state==='approved'" class="sms-secondary" :disabled="busy" @click="control('pause')">{{ t('smsMarketing.pause') }}</button><button v-if="selected.state!=='cancelled'" class="sms-secondary" :disabled="busy" @click="control('cancel')">{{ t('smsMarketing.cancel') }}</button></div></div>
 <p class="text-sm">{{ t('smsMarketing.delivery') }}</p><details v-if="data.history" class="rounded-lg border p-3"><summary>{{ t('smsMarketing.history') }}</summary><p v-for="item in data.history.audit" :key="item.id" class="my-2 break-all text-xs">{{ item.created_at }} · {{ t('smsMarketing.audit.'+item.action) }} · {{ item.campaign_id||'—' }}</p></details><button class="sms-secondary" :disabled="busy" @click="load">{{ t('sms.refresh') }}</button>
 </template></section>
</template>
<style scoped>
.sms-panel{border-radius:1rem;padding:1.5rem;background:#fff;border:1px solid #e5e7eb}
.sms-field{display:flex;flex-direction:column;gap:.5rem;font-size:.875rem;min-width:0}
.sms-field input,.sms-field textarea,.sms-field select{width:100%;border:1px solid #d1d5db;border-radius:.5rem;padding:.65rem;background:transparent}
.sms-check{display:flex;align-items:center;gap:.6rem;font-size:.875rem}
.sms-check input{width:1.1rem;height:1.1rem}
.sms-secondary{min-height:44px;border:1px solid #d1d5db;border-radius:.5rem;padding:.6rem 1rem;font-size:.875rem}
button:disabled{opacity:.55;cursor:not-allowed}th,td{padding:.65rem;text-align:start;white-space:nowrap;border-bottom:1px solid #e5e7eb}
:global(.dark .sms-panel){background:#111827;border-color:#374151}
:global(.dark .sms-field input),:global(.dark .sms-field textarea),:global(.dark .sms-field select){border-color:#4b5563;color:#f3f4f6;background:#111827}
@media(max-width:480px){.sms-panel{padding:1rem}}
</style>
